import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";

// `PALETTE_GROUPS`/`swatchColor` vendored verbatim from `./lib/palette` (a real, readable pure-data
// module). `KitThemeRecord` (from `./lib/themes`) is inlined as the minimal shape this component reads.
interface PaletteToken { name: string; token: string }
interface PaletteGroup { label: string; tokens: PaletteToken[] }
const PALETTE_GROUPS: PaletteGroup[] = [
  { label: "Surfaces", tokens: [
    { name: "canvas", token: "--bg-canvas" },
    { name: "panel", token: "--bg-panel" },
    { name: "elev", token: "--bg-elev" },
    { name: "elev2", token: "--bg-elev2" },
  ] },
  { label: "Text", tokens: [
    { name: "fg", token: "--fg" },
    { name: "muted", token: "--fg-muted" },
    { name: "dim", token: "--fg-dim" },
  ] },
  { label: "Borders", tokens: [
    { name: "border", token: "--border" },
    { name: "soft", token: "--border-soft" },
  ] },
  { label: "Accent", tokens: [
    { name: "accent", token: "--accent" },
    { name: "dim", token: "--accent-dim" },
  ] },
  { label: "Status", tokens: [
    { name: "success", token: "--success" },
    { name: "info", token: "--info" },
    { name: "danger", token: "--danger" },
  ] },
];
function swatchColor(vars: Record<string, string>, token: string): string {
  return vars[token] ?? `var(${token})`;
}

interface KitThemeRecord { id: string; vars?: Record<string, string> }
const SAMPLE_THEME: KitThemeRecord = { id: "warm", vars: { "--accent": "#c4923a", "--bg-canvas": "#181613" } };

export function PaletteStrip({ theme = SAMPLE_THEME }: { theme?: KitThemeRecord }) {
  const vars = theme.vars ?? {};
  return (
    <Box
      style={{ display: "flex", gap: 20, flexWrap: "wrap", alignItems: "flex-start", flex: "none", padding: "10px 16px", borderBottom: "1px solid var(--border-soft)", background: "var(--bg-elev)" }}
    >
      {PALETTE_GROUPS.map((g) => (
        <Box key={g.label} style={{ display: "flex", flexDirection: "column", gap: 5 }}>
          <Eyebrow size={9}>{g.label}</Eyebrow>
          <Box style={{ display: "flex", gap: 6 }}>
            {g.tokens.map((t) => {
              const overridden = t.token in vars;
              return (
                <Box
                  key={t.token}
                  title={`${t.token}${overridden ? ` · ${vars[t.token]}` : " · base default"}`}
                  style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 3 }}
                >
                  <ColorSwatch color={swatchColor(vars, t.token)} size={24} radius={5} style={{ border: "1px solid var(--border)" }} />
                  <Text mono size={9} tone="dim">{t.name}</Text>
                </Box>
              );
            })}
          </Box>
        </Box>
      ))}
    </Box>
  );
}
